"""Staff directory backed by SQLite."""

import sqlite3

STAFF_TABLE = "employees"
BANDS = {1: "Associate", 2: "Senior", 3: "Lead", 4: "Principal"}


class EmployeeDirectory:
    """Departmental lookups over the staff table."""

    def __init__(self, db_path=":memory:"):
        self.conn = sqlite3.connect(db_path)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute(
            f"CREATE TABLE IF NOT EXISTS {STAFF_TABLE} ("
            "badge TEXT PRIMARY KEY, name TEXT NOT NULL, department TEXT NOT NULL, "
            "title TEXT, band INTEGER NOT NULL DEFAULT 1)"
        )
        self.conn.commit()

    def hire(self, badge, name, department, band=1):
        self.conn.execute(
            f"INSERT INTO {STAFF_TABLE} (badge, name, department, title, band) "
            "VALUES (?, ?, ?, ?, ?)",
            (badge, name, department, BANDS[band], band),
        )
        self.conn.commit()

    def by_department(self, department):
        rows = self.conn.execute(
            f"SELECT badge, name, title, band FROM {STAFF_TABLE} "
            "WHERE department = ? ORDER BY name",
            (department,),
        ).fetchall()
        return [dict(row) for row in rows]

    def headcount(self, department):
        row = self.conn.execute(
            f"SELECT COUNT(*) FROM {STAFF_TABLE} WHERE department = ?", (department,)
        ).fetchone()
        return row[0]

    def promote(self, badge):
        row = self.conn.execute(
            f"SELECT band FROM {STAFF_TABLE} WHERE badge = ?", (badge,)
        ).fetchone()
        if row is None:
            raise KeyError(badge)
        band = row["band"] + 1
        if band not in BANDS:
            raise ValueError(f"{badge} is already at the top band")
        self.conn.execute(
            f"UPDATE {STAFF_TABLE} SET band = ?, title = ? WHERE badge = ?",
            (band, BANDS[band], badge),
        )
        self.conn.commit()
        return BANDS[band]

    def transfer(self, badge, department):
        cur = self.conn.execute(
            f"UPDATE {STAFF_TABLE} SET department = ? WHERE badge = ?",
            (department, badge),
        )
        if cur.rowcount == 0:
            raise KeyError(badge)
        self.conn.commit()

    def departments(self):
        rows = self.conn.execute(
            f"SELECT department, COUNT(*) AS n FROM {STAFF_TABLE} "
            "GROUP BY department ORDER BY department"
        ).fetchall()
        return {row["department"]: row["n"] for row in rows}

    def close(self):
        self.conn.close()

"""Library catalog search helpers."""

import sqlite3

CATALOG = "books"
BLOCKED_TOKENS = (";", "--")


def open_catalog(db_path=":memory:"):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    conn.execute(
        f"CREATE TABLE IF NOT EXISTS {CATALOG} ("
        "id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, "
        "author TEXT NOT NULL, year INTEGER, shelf TEXT)"
    )
    conn.commit()
    return conn


def add_book(conn, title, author, year=None, shelf="GEN"):
    cur = conn.execute(
        f"INSERT INTO {CATALOG} (title, author, year, shelf) VALUES (?, ?, ?, ?)",
        (title, author, year, shelf),
    )
    conn.commit()
    return cur.lastrowid


def _check_term(term):
    """Reject search terms carrying SQL statement separators or comment markers."""
    if not isinstance(term, str) or not term.strip():
        raise ValueError("search term must be a non-empty string")
    for token in BLOCKED_TOKENS:
        if token in term:
            raise ValueError(f"search term may not contain {token!r}")
    return term.strip()


def search_by_title(conn, title):
    term = _check_term(title)
    rows = conn.execute(
        f"SELECT id, title, author, year FROM {CATALOG} "
        "WHERE title LIKE ? ORDER BY title",
        (f"%{term}%",),
    ).fetchall()
    return [dict(row) for row in rows]


def search_by_author(conn, author):
    term = _check_term(author)
    rows = conn.execute(
        f"SELECT id, title, author, year FROM {CATALOG} "
        "WHERE author LIKE ? ORDER BY author, title",
        (f"%{term}%",),
    ).fetchall()
    return [dict(row) for row in rows]


def shelve(conn, book_id, shelf):
    cur = conn.execute(
        f"UPDATE {CATALOG} SET shelf = ? WHERE id = ?", (shelf, book_id)
    )
    if cur.rowcount == 0:
        raise KeyError(book_id)
    conn.commit()


def shelf_summary(conn):
    rows = conn.execute(
        f"SELECT shelf, COUNT(*) AS n FROM {CATALOG} GROUP BY shelf ORDER BY shelf"
    ).fetchall()
    return {row["shelf"]: row["n"] for row in rows}


def published_between(conn, first_year, last_year):
    rows = conn.execute(
        f"SELECT id, title, year FROM {CATALOG} "
        "WHERE year BETWEEN ? AND ? ORDER BY year, title",
        (first_year, last_year),
    ).fetchall()
    return [dict(row) for row in rows]

"""Per-folder disk usage summary built on the system du/ls tools."""

import os
import subprocess

UNITS = (("GB", 1024 * 1024), ("MB", 1024), ("KB", 1))


def folder_size_kb(folder):
    """Return the size of one folder in kilobytes, as reported by du."""
    output = subprocess.check_output(["du", "-sk", folder], text=True)
    return int(output.split()[0])


def list_folders(base):
    """Return the immediate entry names under base, sorted."""
    result = subprocess.run(
        ["ls", "-1", base], capture_output=True, text=True, check=False
    )
    if result.returncode != 0:
        return []
    names = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    return sorted(names)


def usage_report(base):
    """Map each subfolder of base to its size in kilobytes."""
    report = {}
    for name in list_folders(base):
        path = os.path.join(base, name)
        if os.path.isdir(path):
            report[name] = folder_size_kb(path)
    return report


def human_size(kilobytes):
    for suffix, factor in UNITS:
        if kilobytes >= factor:
            return f"{kilobytes / factor:.1f} {suffix}"
    return "0.0 KB"


def largest_folders(base, limit=3):
    report = usage_report(base)
    ranked = sorted(report.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:limit]


def format_report(base, limit=3):
    lines = [f"Disk usage under {base}"]
    for name, kilobytes in largest_folders(base, limit):
        lines.append(f"  {name:<24} {human_size(kilobytes):>10}")
    total = folder_size_kb(base)
    lines.append(f"  {'TOTAL':<24} {human_size(total):>10}")
    return "\n".join(lines)

