"""Gym membership credential store."""

import hashlib
import hmac
import os
import sqlite3
import time

MEMBERS = "members"
PLANS = ("basic", "plus", "family")

_PBKDF2_ALGO = "sha256"
_PBKDF2_ITERATIONS = 100_000
_PBKDF2_PREFIX = "pbkdf2_sha256"


class MemberStore:
    """Holds member credentials and plan details for the front-desk app."""

    def __init__(self, db_path=":memory:"):
        self.conn = sqlite3.connect(db_path)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute(
            f"CREATE TABLE IF NOT EXISTS {MEMBERS} ("
            "email TEXT PRIMARY KEY, password_hash TEXT NOT NULL, "
            "plan TEXT NOT NULL DEFAULT 'basic', joined REAL NOT NULL, "
            "active INTEGER NOT NULL DEFAULT 1)"
        )
        self.conn.commit()

    def _hash(self, password, salt=None):
        """Produce a salted PBKDF2-HMAC-SHA256 hash for storage."""
        if salt is None:
            salt = os.urandom(16)
        dk = hashlib.pbkdf2_hmac(
            _PBKDF2_ALGO, password.encode(), salt, _PBKDF2_ITERATIONS
        )
        return f"{_PBKDF2_PREFIX}${_PBKDF2_ITERATIONS}${salt.hex()}${dk.hex()}"

    def _verify_password(self, password, stored):
        if not stored:
            return False
        if stored.startswith(f"{_PBKDF2_PREFIX}$"):
            try:
                _, iter_s, salt_hex, hash_hex = stored.split("$")
                iterations = int(iter_s)
                salt = bytes.fromhex(salt_hex)
                expected = bytes.fromhex(hash_hex)
            except ValueError:
                return False
            dk = hashlib.pbkdf2_hmac(
                _PBKDF2_ALGO, password.encode(), salt, iterations
            )
            return hmac.compare_digest(dk, expected)
        # Legacy plain MD5 hex digest carried over from older records.
        legacy = hashlib.md5(password.encode()).hexdigest()
        return hmac.compare_digest(legacy, stored)

    def register(self, email, password, plan="basic"):
        if plan not in PLANS:
            raise ValueError(f"unknown plan {plan!r}")
        if len(password) < 8:
            raise ValueError("password must be at least 8 characters")
        self.conn.execute(
            f"INSERT INTO {MEMBERS} (email, password_hash, plan, joined) "
            "VALUES (?, ?, ?, ?)",
            (email, self._hash(password), plan, time.time()),
        )
        self.conn.commit()
        return email

    def import_legacy(self, email, md5_hex, plan="basic"):
