}
SOURCE_SUFFIX = ".md"


def settings(overrides=None):
    return {**DEFAULT_CONFIG, **(overrides or {})}


def _page_path(slug, site_root):
    return os.path.join(site_root, slug + SOURCE_SUFFIX)


